"""Agent: Idea Evaluation Agent — wraps HackathonService.evaluate_ideas."""

from __future__ import annotations

from backend.app.agents.state import AgentWorkflowState
from backend.app.services.hackathon_service import HackathonService
from backend.app.schemas.hackathon_guidance import HackathonInput


async def idea_evaluation_agent(state: AgentWorkflowState) -> AgentWorkflowState:
    """Evaluate and score hackathon candidate ideas and populate state['idea_evaluation']."""
    try:
        user_input = dict(state.get("user_input", {}))
        # If candidate ideas were already generated by idea_generator, pass them in
        if state.get("generated_ideas") and "candidate_ideas" not in user_input:
            gen_ideas = state["generated_ideas"].get("ideas", [])
            if gen_ideas:
                user_input["candidate_ideas"] = gen_ideas

        hackathon_input = HackathonInput(**user_input)
        service = HackathonService()
        result = await service.evaluate_ideas(hackathon_input)
        state["idea_evaluation"] = result.model_dump()
        completed = list(state.get("completed_agents", []))
        completed.append("idea_evaluation")
        state["completed_agents"] = completed
        state["current_agent"] = "idea_evaluation"
        state["error"] = None
    except Exception as exc:
        state["error"] = f"idea_evaluation failed: {exc}"
    return state
